class Node {
  int val;
  Node next;
  Node prev;

  Node(int x) {
    val = x;
    next = null;
    prev = null;
  }
}

class ConvertToArray {
  public List<Integer> solve(Node node) {
    Node cur = node;
    while (cur.prev != null) {
      cur = cur.prev;
    }
    List<Integer> res = new ArrayList<>();
    while (cur != null) {
      res.add(cur.val);
      cur = cur.next;
    }
    return res;
  }
}

